 async function loadEpisodes(){const item=state.detail;if(!item)return;state.episodeLoading=true;state.episodeError='';const id=state.episodeRequest=++requestSerial,season=state.season;renderEpisodeArea();try{const r=await fetch(`episodes/${item.key}-${season}.json`);if(r.ok){const data=await r.json();if(state.detail?.key===item.key&&id===state.episodeRequest){state.episodes=data.episodes||[];if(!state.detail.seasonsList&&data.seasons?.length)state.seasons=data.seasons;state.episodeLoading=false;renderEpisodeArea();}}}catch{}if(nativePort&&state.detail?.key===item.key&&id===state.episodeRequest)send({type:'episodes',item,season,requestId:id});else if(['cinemeta','tmdb','streamflix'].includes(item.source)&&!android&&state.detail?.key===item.key&&id===state.episodeRequest){try{const response=await fetch('/title-episodes?source='+item.source+'&id='+encodeURIComponent(item.source==='cinemeta'?item.imdbId:item.id)+'&season='+season);const data=await response.json();if(!response.ok)throw Error(data.error||'Episode information could not load.');receive({type:'episodes',requestId:id,key:item.key,season,data});}catch(error){receive({type:'error',requestId:id,message:error.message});}}else if(state.detail?.key===item.key&&id===state.episodeRequest&&state.episodeLoading){state.episodeLoading=false;state.episodeError='This season is not bundled in the browser preview. The Android app loads episodes from the provider.';renderEpisodeArea();}}
